-- Items organ -- generated by noctusai_lib.domain.items.sql (do not hand-edit)

SET search_path = erp, public;

-- Item categories (tree per org). Unique (org, parent, lower(name)); a parent is always in the same org.
CREATE TABLE IF NOT EXISTS erp.itm_item_categories (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    parent_id   UUID,
    name        TEXT NOT NULL CHECK (length(btrim(name)) > 0),
    is_active   BOOLEAN NOT NULL DEFAULT true,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (org_id, id),
    FOREIGN KEY (org_id, parent_id) REFERENCES erp.itm_item_categories (org_id, id) ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_itm_item_categories_name ON erp.itm_item_categories
    (org_id, COALESCE(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(name));
CREATE INDEX IF NOT EXISTS idx_itm_item_categories_parent ON erp.itm_item_categories (parent_id);
ALTER TABLE erp.itm_item_categories ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "itm_item_categories_select_own_org" ON erp.itm_item_categories;
CREATE POLICY "itm_item_categories_select_own_org" ON erp.itm_item_categories FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('erp')));
DROP POLICY IF EXISTS "service_role_bypass" ON erp.itm_item_categories;
CREATE POLICY "service_role_bypass" ON erp.itm_item_categories FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Items. `sku` unique per org (case-insensitive). Fiscal fields are stored as digits-only text. `cost_cents` is informational until the inventory organ computes average cost. No stock here.
CREATE TABLE IF NOT EXISTS erp.itm_items (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id        UUID NOT NULL,
    sku           TEXT NOT NULL CHECK (sku ~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$'),
    name          TEXT NOT NULL CHECK (length(btrim(name)) > 0),
    description   TEXT,
    item_type     TEXT NOT NULL DEFAULT 'goods' CHECK (item_type IN ('goods', 'service', 'raw_material', 'asset')),
    unit          TEXT NOT NULL DEFAULT 'UN' CHECK (unit IN ('UN', 'KG', 'G', 'L', 'ML', 'M', 'M2', 'M3', 'H', 'CX', 'PCT')),
    category_id   UUID,
    ncm           TEXT CHECK (ncm ~ '^[0-9]{8}$'),
    cest          TEXT CHECK (cest ~ '^[0-9]{7}$'),
    cfop_default  TEXT CHECK (cfop_default ~ '^[123567][0-9]{3}$'),
    origem        SMALLINT CHECK (origem BETWEEN 0 AND 8),
    gtin          TEXT CHECK (gtin ~ '^([0-9]{8}|[0-9]{12,14})$'),
    cost_cents    BIGINT NOT NULL DEFAULT 0 CHECK (cost_cents >= 0),
    price_cents   BIGINT CHECK (price_cents >= 0),
    weight_g      INTEGER CHECK (weight_g >= 0),
    length_mm     INTEGER CHECK (length_mm >= 0),
    width_mm      INTEGER CHECK (width_mm >= 0),
    height_mm     INTEGER CHECK (height_mm >= 0),
    is_active     BOOLEAN NOT NULL DEFAULT true,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (org_id, category_id) REFERENCES erp.itm_item_categories (org_id, id) ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_itm_items_sku ON erp.itm_items (org_id, lower(sku));
CREATE INDEX IF NOT EXISTS idx_itm_items_org_name ON erp.itm_items (org_id, lower(name));
CREATE INDEX IF NOT EXISTS idx_itm_items_category ON erp.itm_items (category_id);
CREATE INDEX IF NOT EXISTS idx_itm_items_gtin ON erp.itm_items (org_id, gtin) WHERE gtin IS NOT NULL;
ALTER TABLE erp.itm_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "itm_items_select_own_org" ON erp.itm_items;
CREATE POLICY "itm_items_select_own_org" ON erp.itm_items FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('erp')));
DROP POLICY IF EXISTS "service_role_bypass" ON erp.itm_items;
CREATE POLICY "service_role_bypass" ON erp.itm_items FOR ALL TO service_role USING (true) WITH CHECK (true);
